-- ============================================================
-- MIGRATION: Insert tourism_spots from tourism_points.csv
-- Source: ../tourism_points.csv
-- Depends on: migrations/insert_spot_categories_from_icons.sql
-- Notes:
--   - Idempotent by slug via ON CONFLICT (slug) DO UPDATE.
--   - Maps CSV subcategory_id values to child spot_categories.code.
--   - EWKB geometries are converted to POINT; non-point geometries use ST_PointOnSurface.
--   - Skips malformed rows listed near the bottom of this file.
-- ============================================================

BEGIN;

WITH source_rows (
  csv_row_no, category_code, name_vi, name_en, slug, description_vi, description_en, address_vi, address_en, phone, email, website, geometry_hex, opening_hours, entrance_fee, currency, rating_avg, rating_count, status, is_featured, created_at, updated_at
) AS (
  VALUES
    (1, 'hang-dong', 'Hang Cả', 'Hang Cả', 'hang-ca-ninh-binh', 'Hang Cả nằm trong khu danh thắng Tràng An, Ninh Bình, là một trong những hang động tự nhiên lớn và đẹp nhất trong quần thể. Hang có chiều dài khoảng 250 mét, uốn lượn qua lòng núi đá vôi hùng vĩ, tạo nên cảnh quan kỳ ảo với những khối nhũ đá lung linh nhiều hình thù khác nhau.
Khi đi thuyền qua Hang Cả, du khách sẽ cảm nhận được không khí mát lạnh, yên tĩnh và huyền bí của thiên nhiên. Ánh sáng phản chiếu từ mặt nước và trần hang tạo nên khung cảnh huyền ảo, khiến Hang Cả trở thành điểm dừng chân yêu thích trong hành trình khám phá Tràng An.', 'Hang Ca (Ca Cave) is located within the Trang An Scenic Landscape Complex in Ninh Binh. It is one of the largest and most beautiful natural caves in the area, stretching about 250 meters through towering limestone mountains.
As visitors take a boat ride through the cave, they can admire stunning stalactites and stalagmites in various shapes, illuminated by the gentle reflections of light from the water. The cool and tranquil atmosphere inside the cave creates a mysterious and magical feeling, making Hang Ca a must-see destination on any Trang An boat tour.', 'Tam Cốc - Bích Động', 'Tam Cốc - Bích Động', NULL, NULL, NULL, '0101000020E6100000EC51B81E857B5A40EE7C3F355E3A3440', '{"default": "6:00 - 18:00"}', 0, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (2, 'hang-dong', 'Hang Hai', 'Hang Hai', 'hang-hai-ninh-binh', 'Hang Hai là hang động thứ hai trong tuyến du lịch sinh thái Tràng An, Ninh Bình. Hang có chiều dài khoảng 60 – 70 mét, với trần hang thấp, uốn lượn mềm mại và được bao phủ bởi những khối nhũ đá óng ánh hình thù độc đáo.', 'Hang Hai (Second Cave) is the second cave on the Trang An eco-tour route in Ninh Binh. The cave is about 60–70 meters long, with a low, winding ceiling decorated by glittering stalactites of fascinating shapes.', 'Tam Cốc - Bích Động', 'Tam Cốc - Bích Động', NULL, NULL, NULL, '0101000020E61000007B14AE47E17A5A4008AC1C5A643B3440', '{"default": "8:00 - 16:30"}', 50000, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (3, 'hang-dong', 'Hang Ba', 'Hang Ba', 'hang-ba-ninh-binh', 'Hang Ba là hang động cuối cùng trong chuỗi ba hang nổi tiếng của tuyến Tràng An (Hang Cả – Hang Hai – Hang Ba). Hang có chiều dài khoảng 100 mét, với trần hang cao và rộng hơn hai hang trước, tạo cảm giác thoáng đãng và tráng lệ khi đi thuyền qua.
Bên trong hang, du khách sẽ được chiêm ngưỡng những khối nhũ đá có hình thù kỳ lạ, được thiên nhiên tạo tác qua hàng triệu năm. Ánh sáng phản chiếu từ mặt nước khiến không gian Hang Ba trở nên lung linh, huyền ảo. Đây là điểm kết thúc tuyệt đẹp cho hành trình khám phá hệ thống hang động kỳ thú của Tràng An.', 'Hang Ba (Third Cave) is the last of the three famous caves on the Trang An boat route (Hang Ca – Hang Hai – Hang Ba). The cave stretches about 100 meters, with a higher and wider ceiling than the previous ones, giving visitors a sense of openness and grandeur.
Inside, magnificent stalactites and stalagmites formed over millions of years create an otherworldly scene. As sunlight reflects off the water, the cave glows with a magical shimmer, making Hang Ba a breathtaking finale to the stunning cave system of Trang An.', 'Tam Cốc - Bích Động', 'Tam Cốc - Bích Động', NULL, NULL, NULL, '0101000020E6100000894160E5D07A5A40CFF753E3A53B3440', '{"default": "8:00 - 16:30"}', 100000, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (4, 'hang-dong', 'Hang Bụt', 'Hang Bụt', 'hang-but-ninh-binh', 'Hang Bụt nằm trong khu du lịch sinh thái Thung Nham, nổi tiếng với vẻ đẹp huyền ảo và những khối nhũ đá mang hình dáng kỳ lạ. Bên trong hang có một khối đá tự nhiên mang hình dáng Đức Phật đang ngồi thiền, vì vậy hang được gọi là Hang Bụt. Đây là điểm đến tâm linh và khám phá thiên nhiên hấp dẫn tại Ninh Bình.', 'Hang But (Buddha Cave) is located in the Thung Nham Ecotourism Area. The cave is famous for its mysterious beauty and unique rock formations, including a natural stone shaped like a meditating Buddha, which gives the cave its name. It’s both a spiritual and natural attraction worth visiting in Ninh Binh.', 'Thung Nham', 'Thung Nham', NULL, NULL, NULL, '0101000020E61000000C022B8716795A40643BDF4F8D373440', '{"default": "6:00 - 18:00"}', 50000, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (5, 'hang-dong', 'Động Vái Giời', 'Động Vái Giời', 'ong-vai-gioi-ninh-binh', 'Động Vái Giời nằm trên núi cao trong khu du lịch Thung Nham, cách mặt đất hơn 400 bậc đá. Tương truyền, đây là nơi xưa kia người dân lên cầu khấn trời đất cho mưa thuận gió hòa. Trong động có ba tầng hang tuyệt đẹp với hệ thống nhũ đá phong phú, lung linh dưới ánh sáng tự nhiên.', 'Vai Gioi Cave is situated high on a mountain in the Thung Nham Ecotourism Area, accessible by climbing over 400 stone steps. Legend has it that locals once came here to pray for favorable weather. The cave features three stunning levels with rich, sparkling stalactite formations illuminated by natural light.', 'Thung Nham', 'Thung Nham', NULL, NULL, NULL, '0101000020E61000008B6CE7FBA9795A409EEFA7C64B373440', '{"default": "7:00 - 17:00"}', 50000, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (6, 'hang-dong', 'Động Thiên Thanh', 'Động Thiên Thanh', 'ong-thien-thanh-ninh-binh', 'Động Thiên Thanh nằm trong quần thể du lịch Động Thiên Hà, được ví như “dải ngân hà trong lòng núi”. Bên trong hang có nhiều khối nhũ đá lấp lánh với hình thù sống động, được ánh sáng chiếu rọi tạo nên khung cảnh huyền ảo và lung linh.', 'Thien Thanh Cave is part of the Thien Ha Cave tourist complex, often called “the Milky Way inside the mountain.” Inside, sparkling stalactites and stalagmites form spectacular shapes, illuminated by soft light that creates a magical, otherworldly atmosphere.', 'KDL Động Thiên Hà', 'KDL Động Thiên Hà', NULL, NULL, NULL, '0101000020E61000003D0AD7A370755A40EE7C3F355E3A3440', '{"default": "6:00 - 18:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (7, 'hang-dong', 'Hang Đột', 'Hang Đột', 'hang-ot-ninh-binh', 'Hang Đột nằm trên tuyến du lịch số 3 của quần thể Tràng An. Hang có cấu trúc dài và hẹp, xuyên qua dãy núi đá vôi với nhiều khối nhũ đá hình thù độc đáo. Khi đi thuyền qua hang, du khách cảm nhận được sự yên tĩnh và mát lạnh giữa thiên nhiên nguyên sơ.', 'Dot Cave is located along Route 3 of the Trang An Scenic Complex. It features a long, narrow passage through limestone mountains, adorned with uniquely shaped stalactites. The cool air and peaceful atmosphere inside the cave offer visitors a refreshing and tranquil experience.', 'Tuyến du lịch 3', 'Tuyến du lịch 3', NULL, NULL, NULL, '0101000020E6100000355EBA490C7A5A406F1283C0CA413440', '{"default": "8:00 - 16:30"}', 100000, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (8, 'hang-dong', 'Hang Vân', 'Hang Vân', 'hang-van-ninh-binh', 'Hang Vân là một trong những hang động đẹp thuộc tuyến số 3 Tràng An. Hang nổi bật với khung cảnh thiên nhiên hài hòa, lòng hang thoáng và phản chiếu ánh sáng lung linh từ mặt nước. Đây là điểm dừng lý tưởng để du khách tận hưởng không gian yên bình và hùng vĩ.', 'Van Cave is one of the beautiful caves on Route 3 of Trang An. It features a spacious chamber with gentle light reflecting off the water, creating a peaceful and majestic atmosphere—perfect for nature lovers and photographers alike.', 'Tuyến du lịch 3', 'Tuyến du lịch 3', NULL, NULL, NULL, '0101000020E6100000FCA9F1D24D7A5A401F85EB51B83E3440', '{"default": "8:00 - 16:30"}', 100000, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (9, 'hang-dong', 'Hang Đại', 'Hang Đại', 'hang-ai-ninh-binh', 'Hang Đại là hang động lớn trên tuyến du lịch số 3 Tràng An, nổi tiếng với vòm hang cao và rộng, tạo cảm giác choáng ngợp khi đi thuyền qua. Các khối nhũ đá trong hang mang hình dáng phong phú, như những tác phẩm điêu khắc tự nhiên kỳ diệu.', 'Dai Cave is a large cave on Route 3 of Trang An, notable for its high and spacious ceiling that impresses visitors as they pass through by boat. The cave’s stalactites form stunning natural sculptures, showcasing the majesty of Ninh Binh’s karst landscape.', 'Tuyến du lịch 3', 'Tuyến du lịch 3', NULL, NULL, NULL, '0101000020E6100000C3F5285C8F7A5A401F85EB51B83E3440', '{"default": "6:00 - 18:00"}', 0, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (10, 'hang-dong', 'Hang Địa Linh', 'Hang Địa Linh', 'hang-ia-linh-ninh-binh', 'Hang Địa Linh là hang đầu tiên trong tuyến du lịch số 1 Tràng An. Hang dài gần 300 mét, xuyên qua dãy núi đá vôi cổ hàng triệu năm tuổi. Bên trong hang, hệ thống nhũ đá và mạch nước ngầm tạo nên không gian huyền ảo, khiến du khách như lạc vào thế giới bí ẩn trong lòng núi.', 'Dia Linh Cave is the first cave on Route 1 of Trang An. Stretching nearly 300 meters through ancient limestone mountains, it features striking stalactites and underground streams that create a mysterious and enchanting atmosphere for travelers.', 'Tuyến du lịch 1', 'Tuyến du lịch 1', NULL, NULL, NULL, '0101000020E6100000355EBA490C7A5A406F1283C0CA413440', '{"default": "7:00 - 17:00"}', 50000, 'VND', 0, 0, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (11, 'hang-dong', 'Hang Tối', 'Dark Cave', 'hang-toi-ninh-binh', 'Hang Tối nổi tiếng với độ dài lớn và không gian rộng, mang đến trải nghiệm thú vị khi đi thuyền trong bóng tối.', 'Dark Cave is famous for its great length and spacious space, offering thrilling boat experiences in darkness.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000006F1283C0CA795A40FCA9F1D24D423440', '{"default": "8:00 - 16:30"}', 200000, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (12, 'hang-dong', 'Hang Sáng', 'Bright Cave', 'hang-sang-ninh-binh', 'Hang Sáng có không gian thoáng đãng, ánh sáng tự nhiên chan hòa, thích hợp để ngắm cảnh khi đi thuyền.', 'Bright Cave has an airy space with abundant natural light, perfect for sightseeing while boating.', NULL, 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000009A99999999795A40508D976E12433440', '{"default": "8:00 - 16:30"}', 200000, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (13, 'hang-dong', 'Hang Nấu Rượu', 'Wine Brewing Cave', 'hang-nau-ruou-ninh-binh', 'Hang động dài 250m gắn liền với truyền thuyết ông khổng lồ nấu rượu, có mạch nước ngầm sâu hơn 10m. Nơi sản xuất rượu cực phẩm tiến vua thời xưa với không khí mát lạnh, trong lành và không gian tĩnh mịch.', 'A 250m long cave associated with the legend of a giant brewing wine, featuring underground water streams over 10m deep. Known for producing premium wine offered to kings in ancient times, with cool, fresh air and serene atmosphere.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C520B07268795A40C3F5285C8F423440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (14, 'hang-dong', 'Hang Ba Giọt', 'Three Drops Cave', 'hang-ba-giot-ninh-binh', 'Hang động dài 200m gắn liền với truyền thuyết mối tình bi thương. Các nhũ đá hình giọt nước tượng trưng cho những giọt nước mắt trong mối tình của chàng trai và cô nương. Nhũ đá muôn hình vạn trạng như con rùa, cây đèn, dàn nhạc.', 'A 200m cave associated with a tragic love legend. Stalactites shaped like water drops symbolize tears from the love story of a young man and a maiden. Features various stalactite formations resembling turtles, lamps, and musical instruments.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000A8C64B3789795A4017D9CEF753433440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (15, 'hang-dong', 'Hang Seo', 'Seo Cave', 'hang-seo-ninh-binh', 'Một trong những hang động đẹp trên tuyến tham quan Tràng An với độ dài trung bình 100-150m. Nhũ đá trong hang có màu trắng muốt và xanh ngọc tuyệt đẹp, tạo nên khung cảnh kỳ ảo.', 'One of the beautiful caves on the Trang An tour route, 100-150m in length. Features pristine white and jade-green stalactites creating a magical scenery.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000008B6CE7FBA9795A40508D976E12433440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (16, 'hang-dong', 'Hang Sơn Dương', 'Son Duong Cave', 'hang-son-duong-ninh-binh', 'Hang động nằm trên tuyến du lịch 1 của Tràng An với độ dài khoảng 150-200m. Hang có hệ thống nhũ đá đa dạng màu sắc và hình thù, mang đến trải nghiệm khám phá thú vị cho du khách.', 'Cave located on Trang An route 1, approximately 150-200m long. Features diverse stalactite systems with various colors and shapes, offering exciting exploration experiences for visitors.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000006F1283C0CA795A4017D9CEF753433440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (17, 'hang-dong', 'Hang Khống', 'Khong Cave', 'hang-khong-ninh-binh', 'Hang động dài 70m gắn liền với Phủ Khống và bí ẩn 100 chiếc quan tài khâm liệm vua Đinh Tiên Hoàng. Hang có không gian rộng lớn với nhũ đá tự nhiên, mang đậm nét tâm linh và lịch sử triều Đinh.', 'A 70m cave connected to Phu Khong Temple and the mystery of 100 coffins used for King Dinh Tien Hoang''s funeral. Features spacious interior with natural stalactites, deeply spiritual and historical significance from the Dinh Dynasty.', 'Thung Khống, Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Khong Valley, Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E610000060E5D022DB795A40F853E3A59B443440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.6, 780, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (18, 'hang-dong', 'Hang Trần', 'Tran Cave', 'hang-tran-ninh-binh', 'Hang động trên tuyến du lịch 1 của Tràng An với hệ thống nhũ đá đa dạng và không gian thoáng đãng. Điểm dừng chân lý tưởng để ngắm cảnh thiên nhiên hoang sơ và chiêm ngưỡng vẻ đẹp kỳ ảo của núi non Ninh Bình.', 'Cave on Trang An route 1 featuring diverse stalactite systems and airy space. An ideal stop to admire pristine nature and the mystical beauty of Ninh Binh''s mountainous landscape.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000001904560E2D7A5A406ABC749318443440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.5, 620, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (19, 'hang-dong', 'Hang Quy Hậu', 'Quy Hau Cave', 'hang-quy-hau-ninh-binh', 'Hang động cuối cùng trên tuyến 1 trước khi trở về bến thuyền. Có không gian yên tĩnh với nhũ đá độc đáo, là nơi kết thúc hành trình khám phá Tràng An đầy ấn tượng.', 'The final cave on route 1 before returning to the boat dock. Features tranquil atmosphere with unique stalactites, marking an impressive end to the Trang An exploration journey.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000001904560E2D7A5A4017D9CEF753433440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (20, 'hang-dong', 'Hang Lấm', 'Lam Cave', 'hang-lam-ninh-binh', 'Hang động đầu tiên trên tuyến 2 của Tràng An với hệ thống nhũ đá phong phú và không gian rộng rãi. Điểm khởi đầu hoàn hảo cho hành trình khám phá các di tích tâm linh và hang động độc đáo.', 'The first cave on Trang An route 2 featuring abundant stalactite systems and spacious interior. A perfect starting point for exploring spiritual sites and unique caves.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000D122DBF97E7A5A401B2FDD2406413440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (21, 'hang-dong', 'Hang Vạng', 'Vang Cave', 'hang-vang-ninh-binh', 'Hang động với hệ thống nhũ đá màu vàng óng ánh độc đáo, tạo hiệu ứng ánh sáng kỳ ảo. Không gian hang rộng và thoáng, mang đến trải nghiệm khám phá thú vị cho du khách.', 'Cave featuring unique golden-hued stalactites creating mystical lighting effects. Spacious and airy interior offers exciting exploration experiences for visitors.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C3F5285C8F7A5A40C74B378941403440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 0, 0, 'active', FALSE, '55:45.8', '22:14.0'),
    (22, 'hang-dong', 'Hang Thánh Trượt', 'Thanh Truot Cave', 'hang-thanh-truot-ninh-binh', 'Hang động mang tên độc đáo với truyền thuyết về thánh nhân. Nhũ đá hình thành các khối đá trơn trượt tự nhiên, tạo nên cảnh quan đặc biệt và không gian yên tĩnh.', 'Uniquely named cave with legends about saints. Natural smooth rock formations create special scenery and tranquil atmosphere.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000D122DBF97E7A5A40AC1C5A643B3F3440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.5, 520, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (23, 'hang-dong', 'Hang Trống', 'Trong Cave (Drum Cave)', 'hang-trong-ninh-binh', 'Hang động nổi tiếng với hiện tượng âm thanh vang vọng như tiếng trống khi đập vào vách đá. Không gian hang rộng với nhũ đá hình thành tự nhiên, mang đến trải nghiệm âm thanh độc đáo.', 'Famous cave with echoing sounds resembling drum beats when striking rock walls. Spacious interior with naturally formed stalactites offers unique acoustic experience.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000295C8FC2F5785A400000000000403440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.6, 720, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (24, 'hang-dong', 'Hang Bói', 'Boi Cave (Fortune-telling Cave)', 'hang-boi-ninh-binh', 'Hang động mang tên gọi độc đáo gắn với tín ngưỡng xưa. Nhũ đá đa dạng hình thù tạo không gian huyền bí, nơi người xưa thường đến cầu khấn và xin lộc.', 'Uniquely named cave associated with ancient beliefs. Diverse stalactite formations create mystical atmosphere, where people once came to pray and seek blessings.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E610000046B6F3FDD4785A40FCA9F1D24D423440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.5, 580, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (25, 'hang-dong', 'Hang Mòi', 'Moi Cave', 'hang-moi-ninh-binh', 'Hang động với lối vào hẹp độc đáo, bên trong mở rộng thành không gian thoáng đãng. Hệ thống nhũ đá phong phú với nhiều hình dáng kỳ thú, thu hút du khách khám phá.', 'Cave with unique narrow entrance opening into spacious interior. Rich stalactite system with various fascinating shapes attracts explorers.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000E17A14AE47795A401B2FDD2406413440', '{"default": "7:00 - 17:00"}', NULL, 'VND', 4.5, 490, 'inactive', FALSE, '55:45.8', '22:14.0'),
    (26, 'nha-thuyen', 'Bến thuyền Trung tâm Tam Cốc', 'Bến thuyền Trung tâm Tam Cốc', 'ben-thuyen-trung-tam-tam-coc-ninh-binh', 'Bến thuyền Trung tâm Tam Cốc là nơi xuất phát cho hành trình khám phá Tam Cốc. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Bến thuyền Trung tâm Tam Cốc là nơi xuất phát cho hành trình khám phá Tam Cốc. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Tam Cốc - Bích Động', 'Tam Cốc - Bích Động', NULL, NULL, NULL, '0101000020E610000079E92631087C5A40643BDF4F8D373440', '{"default": "6:00 - 18:00"}', 0, 'VND', 4.7, 1565, 'active', FALSE, '59:09.1', '22:14.0'),
    (27, 'nha-thuyen', 'Bến thuyền Tràng An', 'Bến thuyền Tràng An', 'ben-thuyen-trang-an-ninh-binh', 'Bến thuyền Tràng An là điểm khởi đầu cho hành trình khám phá Tràng An. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Bến thuyền Tràng An là điểm khởi đầu cho hành trình khám phá Tràng An. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Tuyến du lịch 1, 2, 3', 'Tuyến du lịch 1, 2, 3', NULL, NULL, NULL, '0101000020E6100000986E1283C07A5A408D976E1283403440', '{"default": "6:00 - 18:00"}', 100000, 'VND', 0, 0, 'active', FALSE, '59:09.1', '22:14.0'),
    (28, 'khu-nghi-duong', 'Hoàng Gia', 'Royal Golf Course - Hoang Gia', 'hoang-gia-ninh-binh', 'Sân golf Hoàng Gia nằm tại Tam Điệp, Ninh Bình, được đầu tư lớn và đánh giá là sân golf có quy mô lớn ở Việt Nam. Lorem ipsum dolor sit amet.', 'Hoang Gia golf course located in Tam Diep, Ninh Binh, is a major golf facility in Vietnam.', 'Tam Điệp, Ninh Bình', 'Tam Diep, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000D779944CD87D5A401ED531B238203440', '{"default": "06:00 - 18:00"}', NULL, NULL, NULL, NULL, 'inactive', FALSE, '59:49.1', '27:49.7'),
    (29, 'khu-du-lich', 'Tràng An', 'Trang An', 'trang-an-ninh-binh', 'Khu du lịch Tràng An nổi tiếng với cảnh sắc sông nước và hệ thống hang động, là di sản thiên nhiên thế giới.', 'Trang An scenic area famous for river landscapes and cave systems, designated as a world heritage site.', 'Xã Phú Long, Ninh Bình', 'Phu Long Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E61000007CB7D1B585725A404220478466393440', '{"default": "06:00 - 17:30"}', NULL, NULL, NULL, NULL, 'inactive', FALSE, '59:49.1', '27:56.6'),
    (30, 'khach-san', 'Khách sạn Ninh Bình Legend', 'Ninh Binh Legend Hotel', 'khach-san-ninh-binh-legend-ninh-binh', 'Khách sạn Ninh Bình Legend là khách sạn 5 sao sang trọng nằm tại số 177 Lê Thái Tổ, khu đô thị Xuân Thành, thành phố Ninh Bình. Với 268 phòng nghỉ cao cấp, thiết kế hiện đại, không gian rộng rãi và tiện nghi đạt chuẩn quốc tế, đây là điểm dừng chân lý tưởng cho cả khách du lịch và khách công tác.
Khách sạn có 3 hồ bơi (trong nhà, ngoài trời và hồ vô cực), Sky Bar, Pool Bar, hệ thống nhà hàng phục vụ ẩm thực Á – Âu, spa & wellness, phòng gym, sân tennis và trung tâm hội nghị hiện đại.
Vị trí thuận lợi giúp du khách dễ dàng di chuyển đến các điểm tham quan nổi tiếng như Tràng An, Tam Cốc – Bích Động hay cố đô Hoa Lư.', 'Ninh Binh Legend Hotel is a 5-star luxury hotel located at 177 Le Thai To Street, Xuan Thanh Urban Area, Ninh Binh City. It offers 268 spacious and elegant rooms featuring modern interiors and premium amenities, perfect for both leisure and business stays.
Facilities include three swimming pools (indoor, outdoor, and infinity), a Sky Bar, Pool Bar, fine-dining restaurants serving Asian and Western cuisine, a spa & wellness center, gym, tennis court, and a large conference center.', 'khu đô thị Xuân Thành, phường Hoa Lư, Ninh Bình', 'Xuan Thanh Urban Area, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000CBB947E6547D5A4009BEE9C74D463440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (31, 'khach-san', 'Khách sạn Hoàng Sơn', 'Hoang Son Hotel', 'khach-san-hoang-son-ninh-binh', 'Khách sạn Hoàng Sơn Peace đạt tiêu chuẩn 4 sao và nằm ở số 98 đường Trịnh Tú, phường Ninh Khánh, thành phố Ninh Bình — vị trí trung tâm thuận tiện để di chuyển đến các điểm du lịch như khu danh thắng Tam Cốc – Bích Động, cố đô Hoa Lư hoặc quần thể du lịch tâm linh.', 'Hoang Son Peace Hotel is a 4-star property located at 98 Trinh Tu Street, Ninh Khanh Ward, Ninh Binh City. It’s centrally placed for access to major attractions like Tam Coc – Bich Dong and the ancient capital Hoa Lu.
The hotel features a spacious campus (~15,000 m²) with over 150 contemporary rooms, an outdoor swimming pool, a tennis court, and a restaurant serving Asian and Western cuisine. Room types range from standard doubles to Deluxe and VIP Suites, making the hotel a solid choice for both leisure travellers and event groups.', 'đường Trịnh Tú, phường Hoa Lư, Ninh Bình', 'Trinh Tu Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000CEAFA423C17D5A40B40139A421463440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (32, 'khach-san', 'Khách sạn The Reed', 'The Reed Hotel', 'khach-san-the-reed-ninh-binh', 'The Reed Hotel tọa lạc tại số 1 Đinh Điền, phường Đông Thành, thành phố Ninh Bình — vị trí trung tâm thuận tiện để di chuyển đến các điểm du lịch như Tràng An, Tam Cốc – Bích Động và cố đô Hoa Lư.
Khách sạn đạt tiêu chuẩn 4 sao, với hơn 150 phòng nghỉ hiện đại, được trang bị đầy đủ tiện nghi như bồn tắm riêng, khu tắm đứng, ban công hoặc cửa sổ rộng, hệ thống WiFi tốc độ cao, minibar.
Tiện ích nổi bật gồm hồ bơi ngoài trời ở tầng 4 với tầm nhìn ra thành phố, phòng gym, dịch vụ spa/xông hơi, và các phòng hội nghị – sự kiện lớn.', 'The Reed Hotel is located at 1 Dinh Dien Street, Dong Thanh Ward, Ninh Binh City — a central address with easy access to major attractions such as Trang An, Tam Coc – Bich Dong and the ancient capital Hoa Lu.
This 4-star hotel offers over 150 modern rooms, each well-appointed with amenities including separate bath and shower, high-speed WiFi, minibar and in many cases a balcony or wide window.
Prominent features include an outdoor pool on the 4th floor overlooking the cityscape, a gym, spa/sauna services, and large meeting/conference facilities.', 'đường Đinh Điền, phường Hoa Lư, Ninh Bình', 'Dinh Dien Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E610000077831225927E5A40CB1B832779453440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (33, 'khach-san', 'Khách sạn Hoa Lư', 'Hoa Lu Hotel', 'khach-san-hoa-lu-ninh-binh', 'Khách sạn Hoa Lư là khách sạn tiêu chuẩn 3 sao tọa lạc tại vị trí trung tâm thành phố Ninh Bình, ngay số 1 đường Trần Hưng Đạo, phường Tân Thành. Khách sạn nằm bên cạnh hồ Kỳ Lân và trên quốc lộ 1A, thuận tiện di chuyển đến các điểm du lịch nổi tiếng như Tràng An (~5 km), Cố đô Hoa Lư (~8 km) và Chùa Bái Đính (~12 km).
Lý tưởng cho khách du lịch nghỉ ngơi và công tác, khách sạn có khoảng 75–82 phòng thuộc 6 hạng phòng với nội thất trang bị đầy đủ tiện nghi. Nhà hàng rộng rãi sức chứa từ 300–500 khách phục vụ món Âu-Á và đặc sản Ninh Bình. Với không gian yên tĩnh hướng nhìn ra hồ và thành phố, đây là lựa chọn tốt để nghỉ ngơi và khám phá Ninh Bình.', 'Hoa Lu Hotel is a 3-star property located at 1 Tran Hung Dao Street, Tan Thanh Ward, Ninh Binh City. Positioned beside Ky Lan Lake and along National Highway 1A, it offers easy access to key attractions like Trang An (~5 km), the Ancient Capital Hoa Lu (~8 km) and Bai Dinh Pagoda (~12 km).
The hotel features about 75–82 rooms in 6 categories, all equipped with modern amenities. A spacious restaurant accommodates 300–500 guests and serves European & Asian cuisine as well as local specialties. With a quiet atmosphere and lake/city views, it’s a solid choice for both leisure and business stays in Ninh Binh.', 'đường Trần Hưng Đạo, phường Hoa Lư, Ninh Bình', 'Tran Hung Dao Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E610000004750B88F87D5A40EBFBFA6363433440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (34, 'khach-san', 'Emeralda Tam Cốc Resort', 'Emeralda Tam Coc Resort', 'emeralda-tam-coc-resort-ninh-binh', 'Emeralda Resort Tam Cốc nằm tại thôn Văn Lâm, xã Ninh Hải, huyện Hoa Lư, tỉnh Ninh Bình, ngay sát bến thuyền Tam Cốc – một vị trí đắc địa giữa thiên nhiên non nước Ninh Bình. Resort được thiết kế theo phong cách biệt phủ xứ Kinh Kỳ với mái ngói âm dương, tường vàng và các chi tiết chạm khắc gỗ tinh xảo, mang lại không gian nghỉ dưỡng sang trọng và thanh lịch.
Khu nghỉ gồm các hạng phòng như Superior (36 m²), Deluxe (50 m²), Premium Deluxe (66 m²) và hạng Imperial (88 m²), tất cả đều nhìn ra sông Ngô Đồng hoặc vườn xanh. Tiện nghi nổi bật gồm hồ bơi ngoài trời và bể bơi bốn mùa, phòng gym, spa, hồ thư giãn, dịch vụ cho thuê xe đạp dạo quanh khuôn viên.', 'Emeralda Resort Tam Coc is located in Van Lam Hamlet, Ninh Hai Commune, Hoa Lu District, Ninh Binh Province, right beside the Tam Coc boat pier — offering a prime setting amid Ninh Binh’s scenic limestone karsts and waterways. The resort reflects the grandeur of the “Tonkin villa” style, featuring red tile roofs, yellow walls and intricately carved wooden details, creating a refined and serene retreat.', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000EB73F6F9D77B5A405D9D8C098B373440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (35, 'khach-san', 'Emeralda Resort Ninh Binh', 'Emeralda Resort Ninh Binh', 'emeralda-resort-ninh-binh-ninh-binh', 'Emeralda Resort Ninh Binh nằm tại thôn Tập Ninh, xã Gia Vân, huyện Gia Viễn, tỉnh Ninh Bình — ngay bên cạnh khu bảo tồn thiên nhiên đầm Vân Long. Khu nghỉ dưỡng này được thiết kế theo phong cách làng quê Bắc Bộ truyền thống với mái ngói, cột kèo gỗ, khuôn viên mở giữa thiên nhiên và rừng núi đá vôi.
Khu resort gồm khoảng 172 phòng nghỉ (phân khu theo “xóm làng”), mỗi phòng đều hướng ra vườn, hồ hoặc cảnh thiên nhiên xung quanh. Tiện nghi nổi bật gồm hồ bơi ngoài trời và trong nhà, spa cao cấp, khu gym, nhà hàng đa dạng và không gian thư giãn lý tưởng cho cả gia đình và cặp đôi. Vị trí cách Hà Nội khoảng 90 phút di chuyển bằng ô tô — rất thuận tiện cho kỳ nghỉ ngắn giữa thiên nhiên.
Emeralda Resort Ninh Binh là lựa chọn lý tưởng nếu bạn tìm một nơi lưu trú vừa sang trọng, vừa gần gũi thiên nhiên, mang lại cảm giác thư giãn thực sự giữa vùng đất cố đô Hoa Lư.', 'Emeralda Resort Ninh Binh is located in Tap Ninh Hamlet, Gia Van Commune, Gia Vien District, Ninh Binh Province — adjacent to the Van Long Nature Reserve. This resort is styled as a Northern Vietnamese countryside village with traditional roof-tiles, timber columns and open spaces surrounded by karst mountains and wetlands.
The property features around 172 guest rooms organized in village-style clusters; each room offers views of garden, pool or nature. Key amenities include outdoor and indoor swimming pools, a premium spa, fitness centre, multiple restaurants and a tranquil environment suited for families and couples alike. With a drive of approximately 90 minutes from Hanoi, it’s an ideal get-away to nature from the city.
Emeralda Resort Ninh Binh is a perfect pick for those seeking upscale accommodation close to nature, in a setting that blends comfort and the heritage of Northern Vietnam.', 'xã Gia Vân, Ninh Bình', 'Gia Van Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E61000005D3BCAB92F785A40D98232C2365E3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (36, 'khach-san', 'Khách sạn Hidden Charm', 'Hidden Charm Hotel', 'khach-san-hidden-charm-ninh-binh', 'Khách sạn Hidden Charm nằm trong khu du lịch Tam Cốc–Bích Động, thôn Văn Lâm, xã Ninh Hải, huyện Hoa Lư, tỉnh Ninh Bình — một vị trí tuyệt đẹp, giữa những cánh đồng lúa uốn lượn và núi đá vôi trùng điệp.
Khách sạn được thiết kế như một boutique resort sang trọng với khoảng 98 phòng nghỉ trang nhã, sử dụng gam màu ấm, các chi tiết gốm mosaic, vật dụng thủ công mỹ nghệ, và hướng nhìn ra cảnh thiên nhiên bao quanh.', 'The boutique-style resort features about 98 elegantly furnished rooms, decorated with warm tones, mosaic ceramics and artisan details, all offering views of nature. Facilities include an outdoor pool, spa, international restaurant, and children’s play area. Ideal for families and leisure travellers seeking a peaceful, nature-rich stay.', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000CB17671C547C5A400EB98763AA373440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (37, 'khach-san', 'Khách sạn Thuận Thành', 'Thuan Thanh Hotel', 'khach-san-thuan-thanh-ninh-binh', 'Khách sạn Thuận Thành nằm ở vị trí trung tâm tại phố Kim Đa, phường Ninh Khánh, thành phố Ninh Bình — trên trục đường Đinh Tiên Hoàng, rất thuận tiện để di chuyển tới các điểm du lịch nổi tiếng của Ninh Bình như Cố đô Hoa Lư, Tam Cốc – Bích Động và Đền Thái Vi.', 'Thuan Thanh Hotel is centrally located on Kim Da Street, Ninh Khanh Ward, Ninh Binh City — right on the main avenue Dinh Tien Hoang, offering excellent access to major Ninh Binh attractions like Hoa Lu Citadel, Tam Coc–Bich Dong and Thai Vi Temple', 'đường Đinh Tiên Hoàng, Phường Hoa Lư, Ninh Bình', 'Dinh Tien Hoang Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E61000000F8C51D8017E5A40FB7DF130AB473440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (38, 'khach-san', 'Khách sạn Tuylip', 'Tuylip Hotel', 'khach-san-tuylip-ninh-binh', 'Khách sạn Tulip Ninh Bình là khách sạn tiêu chuẩn khoảng 3 sao nằm tại số 181/9 đường Đinh Tiên Hoàng, phường Ninh Khánh, thành phố Ninh Bình. Khách sạn sở hữu khuôn viên rộng lớn với hơn 20 ha, kiến trúc hiện đại kết hợp cổ điển và nhiều tiện nghi như hồ bơi ngoài trời, công viên nước theo mùa, nhà hàng buffet, khu spa/massage, phòng họp & hội nghị.', 'Tulip Hotel Ninh Binh is a roughly 3-star hotel located at 181/9 Dinh Tien Hoang Street, Ninh Khanh Ward, Ninh Binh City. The property covers over 20 hectares with modern and classic architectural elements, and offers amenities such as an outdoor swimming pool, seasonal water-park, buffet restaurant, spa/massage area and meeting & conference rooms', 'đường Đinh Tiên Hoàng, phường Hoa Lư, Ninh Bình', 'Dinh Tien Hoang Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000311D3E7FED7D5A40AD770394BF473440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (39, 'khach-san', 'Khách sạn The Vissai', 'The Vissai Hotel', 'khach-san-the-vissai-ninh-binh', 'Khách sạn The Vissai nằm tại số 848, đường Trần Hưng Đạo, phường Tân Thành, thành phố Ninh Bình – vị trí trung tâm thuận tiện cho việc tham quan các điểm du lịch nổi bật trong và quanh Ninh Bình.
Khu nghỉ dưỡng đạt tiêu chuẩn cao cấp với đa dạng hạng phòng: từ hạng Superior/Deluxe cho đến Executive, Suite, Family và Triple – mỗi phòng đều trang bị đầy đủ tiện nghi hiện đại như điều hoà, TV màn hình lớn, minibar, két an toàn và WiFi tốc độ cao.', 'The Vissai Hotel is located at 848 Tran Hung Dao Street, Tan Thanh Ward, Ninh Binh City – a central and convenient position for exploring Ninh Binh’s major tourist attractions.
This upscale hotel offers a variety of room categories—from Superior/Deluxe to Executive, Suite, Family, and Triple rooms—each equipped with modern amenities such as air-conditioning, large flat-screen TVs, minibar, safe and high-speed WiFi', 'đường Trần Hưng Đạo, phường Hoa Lư, Ninh Bình', 'Tran Hung Dao Street, Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000BFB0A658167E5A40B402BCB556423440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (40, 'khach-san', 'Wyndham Grand Vedana Ninh Binh Resort', 'Wyndham Grand Vedana Ninh Binh Resort', 'wyndham-grand-vedana-ninh-binh-resort-ninh-binh', 'Wyndham Grand Vedana Ninh Bình là khu nghỉ dưỡng 5-sao nằm giữa thiên nhiên hùng vĩ của huyện Nho Quan, tỉnh Ninh Bình. Resort được thiết kế hiện đại kết hợp với cảnh quan hồ, suối và núi đá vôi; các phòng nghỉ, bungalow và villa hướng ra hồ hoặc vườn, có nhiều lựa chọn phù hợp từ cặp đôi tới gia đình.
Tiện nghi nổi bật: hồ bơi ngoài trời, onsen/bể khoáng nóng trong nhà, spa & wellness, khu gym, dịch vụ thuê xe đạp, kayak trên hồ, nhà hàng đa dạng ẩm thực Việt - Âu, khu tổ chức sự kiện và hội nghị. Giá tham khảo phòng tiêu chuẩn từ khoảng VND 1.500.000-3.500.000/đêm, tùy loại phòng và thời điểm.
Đây là lựa chọn lý tưởng cho những ai muốn kết hợp nghỉ dưỡng cao cấp với trải nghiệm thiên nhiên, yên tĩnh và tiện nghi tại Ninh Bình.', 'Wyndham Grand Vedana Ninh Binh Resort is a 5-star luxury resort set in the lush natural landscape of Nho Quan District, Ninh Binh Province. The property blends modern design with lakeside and mountain surroundings, offering rooms, bungalows and villas with garden, lake or forest views suitable for couples and families alike.
Key features include an outdoor pool, indoor hot-spring onsen, spa & wellness centre, fitness gym, bike & kayak rental, a diverse Vietnamese–Western restaurant, and event/meeting facilities. Rates typically start from VND 1.5 million – 3.5 million per night, depending on room type and season.
Ideal for travellers seeking premium comfort and nature immersion in Ninh Binh.', 'xã Cúc Phương, Ninh Bình', 'Cuc Phuong Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000B3979C43946E5A40A0591AEF7B423440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (41, 'khach-san', 'Khách sạn Lakeside II', 'Lakeside II Hotel', 'khach-san-lakeside-ii-ninh-binh', 'Khách sạn Lakeside II nằm tại số 168 Đường Đông A, phường Lộc Vượng, thành phố Nam Định — vị trí trung tâm thành phố, thuận tiện di chuyển đến các điểm du lịch và trung tâm thương mại. Khách sạn đạt tiêu chuẩn 3 sao với khoảng 60 phòng nghỉ hiện đại, được trang bị điều hòa nóng/lạnh, minibar, két an toàn, WiFi miễn phí và thường có ban công hoặc cửa sổ rộng. Hạng phòng đa dạng từ Standard (~26-28 m²) đến Deluxe (35-40 m²) với mức giá tham khảo từ khoảng 550.000 đ/đêm cho phòng cơ bản đến 1.100.000 đ/đêm cho hạng Deluxe. Khách sạn phù hợp cho khách công tác hoặc khách tham quan ngắn ngày muốn một nơi lưu trú tiện nghi và ở ngay trung tâm thành phố', 'Lakeside II Hotel is located at 168 Dong A Street, Loc Vuong Ward, Nam Dinh City — a central location with easy access to city landmarks and shopping. This 3-star hotel offers about 60 modern rooms, well-equipped with air-conditioning, minibar, safety box, free WiFi and many rooms with balconies or large windows. Room categories range from Standard (~26-28 m²) to Deluxe (35-40 m²), with price range starting around VND 550,000/night for basic rooms up to about VND 1,100,000/night for Deluxe. It’s a comfortable choice for business travellers or short-stay visitors wanting convenience in the city centre.', 'phường Nam Định, Ninh Bình', 'Nam Dinh Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E61000008662705BE3895A40F79A8EA120703440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (42, 'khach-san', 'Tru by Hilton Nam Dinh City Centre', 'Tru by Hilton Nam Dinh City Centre', 'tru-by-hilton-nam-dinh-city-centre-ninh-binh', 'Tru by Hilton Nam Định City Centre là khách sạn tiêu chuẩn quốc tế thuộc thương hiệu Hilton (nhóm “Tru by Hilton”), tọa lạc tại số 272 đường Trần Hưng Đạo, phường Cửa Bắc, thành phố Nam Định — ngay trung tâm thành phố thuận tiện cho việc tham quan, mua sắm và ẩm thực địa phương.
Khách sạn cung cấp phòng nghỉ hiện đại với các tiện nghi như WiFi miễn phí, bữa sáng nóng miễn phí, đỗ xe tự phục vụ miễn phí và phòng tập gym. Thiết kế phòng hướng đến sự trẻ trung, tiện lợi và thoải mái — phù hợp cho khách công tác, du lịch đơn giản hoặc nghỉ ngơi ngắn ngày.', 'Tru by Hilton Nam Dinh City Centre is a centrally located hotel under the Hilton brand’s Tru series, positioned at 272 Tran Hung Dao Street, Cua Bac Ward, Nam Dinh City. The hotel offers contemporary, streamlined rooms alongside complimentary hot breakfast, free self-parking and free high-speed WiFi. With a fitness centre and a modern, practical design, the property is well-suited for short leisure stays or business trips. Its central location and competitive room rates make it an attractive option for travelers seeking comfort and convenience in Nam Dinh.', 'phường Nam Định, Ninh Bình', 'Nam Dinh Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000FF8090D4228B5A40DC8E605FC66D3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (43, 'khach-san', 'Khách xá Tam Chúc', 'Tam Chuc Guest House', 'khach-xa-tam-chuc-ninh-binh', 'Khách xá Tam Chúc nằm ngay trong khuôn viên Chùa Tam Chúc (thị trấn Ba Sao, huyện Kim Bảng, tỉnh Hà Nam) — một lựa chọn lưu trú thuận tiện cho du khách muốn trải nghiệm không gian tâm linh, thiên nhiên và nghỉ dưỡng.', 'Tam Chuc Guest House is situated inside the grounds of Tam Chuc Temple Complex (Ba Sao Town, Kim Bang District, Ha Nam Province) — a highly convenient choice for visitors seeking a combination of spiritual experience, nature and relaxation.', 'phường Tam Chúc, Ninh Bình', 'Tam Chuc Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E61000005CE337CCC8725A40F7FCDE70CD8D3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (44, 'khach-san', 'Mường Thanh Luxury Hà Nam', 'Muong Thanh Luxury Ha Nam', 'muong-thanh-luxury-ha-nam-ninh-binh', 'Khách sạn Mường Thanh Luxury Hà Nam là khách sạn tiêu chuẩn 5 sao nằm tại trung tâm thành phố Phủ Lý, tỉnh Hà Nam. Tọa lạc gần sông Đáy, khách sạn có hơn 190 phòng nghỉ sang trọng, hiện đại với thiết kế hướng tới sự thư giãn và tiện nghi.
Khách sạn có nhiều tiện ích nổi bật như hồ bơi ngoài trời, spa & massage, phòng tập gym, sân tennis – cầu lông và nhà hàng lớn phục vụ buffet sáng. Vị trí thuận lợi giúp du khách dễ dàng kết hợp nghỉ dưỡng và tham quan các điểm gần như chùa Tam Chúc, thành phố Hà Nam, hoặc di chuyển tới Hà Nội.', 'Muong Thanh Luxury Ha Nam Hotel is a 5-star property located in the centre of Phu Ly city, Ha Nam Province. Situated near the Day River, the hotel offers over 190 modern, luxurious rooms designed for comfort and relaxation.
The hotel features standout amenities including an outdoor swimming pool, spa and massage services, fitness centre, tennis-badminton court and a large restaurant serving buffet breakfast. Its strategic location allows guests to combine leisure with visits to nearby attractions such as Tam Chuc Pagoda or Ha Nam city, and convenient access to Hanoi.', 'phường Phủ Lý, Ninh Bình', 'Phu Ly Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C1B2F2DF627A5A40A9B6AF0FC78A3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (45, 'khach-san', 'Khách sạn Hòa Bình', 'Hoa Binh Hotel', 'khach-san-hoa-binh-ninh-binh', 'Khách sạn Hòa Bình tọa lạc tại số 1 đường Đinh Tiên Hoàng, phường Tân Thành, thành phố Ninh Bình. Với tiêu chuẩn 3-sao, khách sạn cung cấp các phòng nghỉ hiện đại, sạch sẽ với đầy đủ tiện nghi như điều hòa, TV, WiFi miễn phí và ban công nhìn ra thành phố hoặc núi đá. Khách sạn có nhà hàng phục vụ buffet sáng với cả món Việt và món Âu, thuận tiện cho khách du lịch tham quan khu vực như Tràng An, Tam Cốc – Bích Động, hay cố đô Hoa Lư. Giá tham khảo từ khoảng 600.000 đ/đêm cho phòng đôi tiêu chuẩn.', 'Located at 1 Dinh Tien Hoang Street, Tan Thanh Ward, Ninh Binh City, Hoa Binh Hotel is a 3-star property offering modern rooms equipped with air-conditioning, TV and free WiFi. Many rooms feature balconies with views of the city or surrounding limestone hills. The in-house restaurant serves a buffet breakfast combining Vietnamese and Western dishes. The hotel is conveniently situated for visitors exploring major attractions such as Trang An, Tam Coc–Bich Dong and the ancient Hoa Lu citadel. Room rates start from approximately VND 600,000 per night for a standard double room', 'phường Phủ Lý, Ninh Bình', 'Phu Ly Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C61A718D5E7A5A4071F76CD6698B3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (46, 'khach-san', 'Vinpearl Melia Phủ Lý', 'Vinpearl Melia Phu Ly', 'vinpearl-melia-phu-ly-ninh-binh', 'Meliá Vinpearl Phủ Lý là khách sạn – căn hộ khách sạn 5 sao nằm tại số 60 đường Biên Hòa, phường Minh Khai, thành phố Phủ Lý, tỉnh Hà Nam. Tòa nhà cao 27 tầng, hiện đại và nổi bật giữa trung tâm thành phố.
Khách sạn cung cấp khoảng 180 phòng và căn hộ từ diện tích ~31 m² đến ~75 m², với nội thất cao cấp, mang lại cảm giác ấm cúng như ở nhà nhưng vẫn sang trọng.
Tiện nghi nổi bật: hồ bơi trong nhà (4 mùa), trung tâm spa – gym, nhà hàng buffet và gọi món, quầy bar, các phòng họp/hội nghị hiện đại, vị trí thuận tiện di chuyển từ Hà Nội (~60 km) hoặc sân bay Nội Bài (~85 km).
Giá tham khảo bắt đầu từ khoảng 1.290.000 đ/đêm cho phòng tiêu chuẩn ăn sáng.
Là lựa chọn lý tưởng cho du khách nghỉ dưỡng hoặc công tác tại Hà Nam – Phủ Lý, kết hợp khám phá các điểm du lịch lân cận', 'Meliá Vinpearl Phu Ly is a 5-star hotel & serviced apartments located at 60 Bien Hoa Street, Minh Khai Ward, Phu Ly City, Ha Nam Province. The 27-storey building offers around 180 rooms and suites ranging from ~31 m² to ~75 m², blending luxurious interior with a cozy home-like feel.
Key amenities include an indoor all-season swimming pool, spa & fitness centre, buffet and à-la-carte dining, bar, and modern meeting rooms. Conveniently accessible from Hanoi (~60 km) and Noi Bai Airport (~85 km), it’s suitable for both leisure and business travellers. Room rates start from about VND 1,290,000/night including breakfast.', 'phường Phủ Lý, Ninh Bình', 'Phu Ly Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000BEA36826B37A5A40DA6BC82A288B3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (47, 'khach-san', 'Khách sạn Yến Nhi', 'Yen Nhi Hotel', 'khach-san-yen-nhi-ninh-binh', 'Khách sạn Yến Nhi nằm ở khu vực trung tâm của khu du lịch Tam Cốc – Bích Động, huyện Hoa Lư, tỉnh Ninh Bình — thuận tiện để tham quan nhiều điểm nổi bật của vùng như chùa Bái Đính, Vân Long, Tràng An. Khách sạn đạt chuẩn 3 sao với khoảng 100 phòng nghỉ khép kín, thiết kế hiện đại kết hợp với phong cách cổ điển, có ban công hoặc cửa sổ hướng ra cánh đồng hoặc núi đá. Các tiện nghi phòng bao gồm điều hòa hai chiều, WiFi miễn phí, minibar, TV, nước nóng — phù hợp cho cả khách du lịch và khách công tác. Ngoài ra, khách sạn có nhà hàng lớn phục vụ món ăn địa phương nổi bật như dê Ninh Bình, khu hội nghị – hội thảo và bể bơi ngoài trời, đáp ứng cả nhu cầu nghỉ dưỡng và sự kiện', 'Yen Nhi Hotel is located in the heart of the Tam Coc – Bich Dong tourist area in Hoa Lu District, Ninh Binh Province. It holds a 3-star rating with around 100 ensuite rooms, blending modern amenities with classical touches, many with views of rice fields or limestone karsts. Room features include two-way air-conditioning, free WiFi, minibar, flat-screen TV, and hot water — suitable for leisure or business travellers. The hotel also offers a large restaurant (serving local specialties such as Ninh Binh goat), event/conference rooms, and an outdoor swimming pool, making it a versatile option for both relaxation and meetings', 'Phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000E6B2D1393F7C5A40A0A70183A4373440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (48, 'khach-san', 'Khách sạn Vân Long Green', 'Van Long Green Hotel', 'khach-san-van-long-green-ninh-binh', 'Khách sạn Vân Long Green tọa lạc ngay khu du lịch sinh thái Khu bảo tồn thiên nhiên Vân Long, thôn Tập Ninh, xã Gia Vân, huyện Gia Viễn, tỉnh Ninh Bình. Từ vị trí này, du khách thuận tiện tiếp cận vùng đầm nước và cảnh quan đá vôi đặc trưng.
Tòa nhà chính được thiết kế với mặt ngoài phủ dây leo xanh tạo cảm giác hoà mình với thiên nhiên và giảm nhiệt cho không gian bên trong. Tầng 1 là khu lễ tân, nhà hàng, quầy bar; tầng 2 và tầng 3 gồm khoảng 60 phòng nghỉ với diện tích đa dạng từ 20 m² đến 120 m² — phù hợp cho khách đơn, đôi hoặc nhóm.
Khách sạn cũng có khu vực tổ chức sự kiện ngoài trời rộng khoảng 450 m², bãi đỗ xe cho 50–70 ô tô, nhà hàng và bar phục vụ ẩm thực – đồ uống. Đây là lựa chọn lý tưởng cho du khách vừa muốn nghỉ ngơi, vừa muốn khám phá thiên nhiên và sinh thái Vân Long.', 'Van Long Green Hotel is located right at the Van Long ecotourism area in Tap Ninh Hamlet, Gia Van Commune, Gia Vien District, Ninh Binh Province. Its prime waterside location allows easy access to the subtle landscapes of the Van Long wetland and limestone karsts.
The building exterior is covered in climbing plants, creating a green façade and a naturally cool environment. The ground floor houses a reception, souvenir shop, restaurant and bar; the upper floors number around 60 rooms of varying sizes (20 m² to 120 m²), suitable for solo travellers, couples or groups.
The hotel also includes a large outdoor event space (~450 m²), parking for 50–70 cars, and onsite F&B services. It’s a strong choice for those seeking a restful stay while exploring nature at Van Long.', 'xã Gia Vân, Ninh Bình', 'Gia Van Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000CB14731074785A40CB811E6ADB5C3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (49, 'khach-san', 'Aquarius Garden', 'Aquarius Garden', 'aquarius-garden-ninh-binh', 'Aquarius Garden nằm tại thôn Gọng Vó, xã Gia Hòa, huyện Gia Viễn, tỉnh Ninh Bình, giữa không gian thanh bình của khu sinh thái Vân Long. Khu nghỉ dưỡng nổi bật với kiến trúc gần gũi thiên nhiên, gồm các bungalow gỗ và phòng nghỉ hướng vườn, hồ hoặc núi. Nơi đây có hồ bơi ngoài trời, nhà hàng phục vụ món ăn đặc sản địa phương và khu vườn xanh mát rộng rãi. Du khách có thể đạp xe, đi dạo hoặc đơn giản là tận hưởng không gian yên tĩnh, thư giãn giữa thiên nhiên. Aquarius Garden là điểm đến lý tưởng cho những ai muốn nghỉ dưỡng nhẹ nhàng và hòa mình vào không khí trong lành của Ninh Bình.', 'Aquarius Garden is located in Gong Vo Hamlet, Gia Hoa Commune, Gia Vien District, Ninh Binh. Nestled in the peaceful Van Long ecological area, the resort offers a natural and relaxing retreat with wooden bungalows and garden-view or mountain-view rooms. It features an outdoor pool, a local-cuisine restaurant, and a lush garden surrounded by nature. Guests can enjoy cycling, walking, or simply relaxing in the tranquil atmosphere. Aquarius Garden is an ideal destination for those seeking peace, comfort, and connection with nature in Ninh Binh', 'Xã Gia Viễn, Ninh Bình', 'Gia Vien Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E61000008D28ED0DBE765A4052616C21C8613440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (50, 'khach-san', 'Cúc Phương Mineral Retreat', 'Cuc Phuong Mineral Retreat', 'cuc-phuong-mineral-retreat-ninh-binh', 'Cúc Phương Mineral Retreat tọa lạc tại thôn Đồng Tâm, huyện Nho Quan, tỉnh Ninh Bình — nằm trong khu vực thiên nhiên xanh rộng lớn trên 100 ha thuộc quần thể du lịch Vườn quốc gia Cúc Phương – Tràng An Landscape Complex', 'Cúc Phương Mineral Retreat is located in Dong Tam Hamlet, Nho Quan District, Ninh Binh Province — set within a green expanse of over 100 hectares in the Cuc Phuong – Trang An tourism complex', 'xã Cúc Phương, Ninh Bình', 'Cuc Phuong Commune, Ninh Binh', NULL, NULL, NULL, '0101000020E610000017821C94306F5A4029965B5A0D413440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (51, 'khach-san', 'Athena Premier Resort', 'Athena Premier Resort', 'athena-premier-resort-ninh-binh', 'Athena Premier Resort tọa lạc tại thôn Khả Lương, xã Ninh Thắng, huyện Hoa Lư, tỉnh Ninh Bình — trong khu vực cảnh quan di sản nổi tiếng ở Ninh Bình. 
Khu nghỉ dưỡng mang tiêu chuẩn quốc tế, kết hợp giữa phong cách hiện đại và kiến trúc gần gũi thiên nhiên: các phòng có ban công hướng hồ và cánh đồng; xung quanh là cảnh ruộng lúa, núi đá vôi hùng vĩ.', 'Athena Premier Resort is an international-standard resort located in Khả Lương Village, Ninh Thắng Commune, Hoa Lư District, Ninh Bình Province — within a heritage landscape zone in the region.
The resort combines modern luxury with natural surroundings: rooms with balconies overlooking lakes and rice fields, nestled amid limestone karsts and scenic countryside', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000FFCA4A93527C5A4029D027F224393440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (52, 'khach-san', 'Thung Nham Resort', 'Thung Nham Resort', 'thung-nham-resort-ninh-binh', 'Thung Nham Resort nằm tại thôn Hải Nham, xã Ninh Hải, huyện Hoa Lư, tỉnh Ninh Bình — bên trong khu du lịch sinh thái rộng hơn 300 ha ở vùng lõi Tràng An. 
Khu nghỉ dưỡng hoà mình cùng thiên nhiên — núi non, rừng, hồ nước — mang lại không gian yên bình để “sống chậm lại”', 'Thung Nham Resort is located in Hai Nham village, Ninh Hai commune, Hoa Lư district, Ninh Binh province — within a more than 300-hectare eco-tourism zone in the core of the Trang An landscape.
This resort offers a nature-immersed retreat amid mountains, forests and lakes — a place to slow down, relax and reset.', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E61000001361C3D32B795A402B8716D9CE373440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (53, 'khach-san', 'Memorina Ninh Bình Famstay', 'Memorina Ninh Binh Famstay', 'memorina-ninh-binh-famstay-ninh-binh', 'Khu nghỉ dưỡng kết hợp mô hình farm-stay (nghỉ dưỡng + nông trại) với thiết kế mang phong cách làng quê Bắc Bộ: không gian xanh mát, ruộng vườn, hoạt động trải nghiệm dân gian như trồng rau, cấy lúa, chèo thuyền', 'Memorina Ninh Binh Farmstay is located at Hamlet 1, Gia Sinh Commune, Gia Viễn District, Ninh Binh Province — less than 1 km from Bai Dinh Pagoda. With a unique blend of resort comfort and rural farm experience, it offers a green, countryside-inspired setting where guests can relax amid gardens, rice fields and lakes. The guest accommodations range from Garden View Deluxe rooms to Lake View Suites and Villas, all equipped with modern amenities such as flat-screen TVs, in-room safes and free WiFi. Signature features include an outdoor swimming pool, on-site organic farm supplying the restaurant, and hands-on countryside activities such as planting vegetables, rice-field work and boat rides around the resort.', 'Phường Tây Hoa Lư, Ninh Bình', 'Tay Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E61000004A0C022B87765A4025068195434B3440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (54, 'khach-san', 'Tam Cốc Lamontagne Resort & spa', 'Tam Coc Lamontagne Resort & Spa', 'tam-coc-lamontagne-resort-spa-ninh-binh', 'Tam Cốc La Montagne Resort & Spa tọa lạc tại làng Đàm Khê, xã Ninh Hải, huyện Hoa Lư, tỉnh Ninh Bình, giữa những cánh đồng lúa và các núi đá vôi hùng vĩ — khu vực được ví như “Vịnh Hạ Long trên cạn”', 'Tam Coc La Montagne Resort & Spa is situated in Dam Khe Village, Ninh Hai Commune, Hoa Lu District, Ninh Binh Province, nestled amidst rice paddies and towering limestone karsts — often described as the “Halong Bay on land”', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000145CACA8C17A5A40478FDFDBF4373440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (55, 'khach-san', 'Jiva Hoa Lư Retreat', 'Jiva Hoa Lu Retreat', 'jiva-hoa-lu-retreat-ninh-binh', 'Tọa lạc trong thung lũng núi đá vôi thuộc di sản Tràng An Landscape Complex (Hoa Lư, Ninh Bình), Jiva Hoa Lu Retreat mang đến không gian nghỉ dưỡng sang trọng giữa thiên nhiên bao la với cảnh ruộng lúa, núi đá và sông suối', 'Nestled in a lush valley within the UNESCO-listed Trang An landscape in Hoa Lư, Ninh Binh, Jiva Hoa Lu Retreat is a luxury hideaway surrounded by rice paddies, dramatic limestone karsts and pristine nature. With private-pool villas, spacious suites and deluxe rooms featuring mountain or garden views, the property blends Northern Vietnamese architecture with modern comforts. Guests can enjoy an all-day restaurant, fine-dining in a restored 120-year-old church, a bespoke wine lounge, a wellness spa, an outdoor pool, complimentary bikes and curated cultural activities. Sustainability is embedded in its operations—from solar panels to local sourcing and community partnerships', 'phường Nam Hoa Lư, Ninh Bình', 'Nam Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000CC457C27667B5A40EF552B137E393440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (56, 'khach-san', 'Bái Đính garden Resort & spa', 'Bai Dinh Garden Resort & Spa', 'bai-inh-garden-resort-spa-ninh-binh', 'Nằm ngay cạnh Chùa Bái Đính linh thiêng và giữa vùng cảnh quan di sản tại tỉnh Ninh Bình, resort này mang đến một không gian nghỉ dưỡng yên bình giữa xanh mát. Khu gồm các tòa khách sạn và bungalow, được bao quanh bởi vườn cây và hồ bơi ngoài trời rộng. Nội thất kết hợp giữa phong cách hiện đại và đồ thủ công mỹ nghệ truyền thống, mỗi phòng đều có sân hiên riêng, trang bị tiện nghi đầy đủ. Dịch vụ nổi bật: nhà hàng ẩm thực Việt-Âu, spa Lantern, hồ bơi, cho thuê xe đạp miễn phí và giao thông thuận tiện để khám phá các điểm du lịch lân cận', 'Located adjacent to the sacred Bai Dinh Pagoda complex and nestled in the heritage-rich landscape of Ninh Binh, this resort offers a tranquil retreat surrounded by gardens and an outdoor pool. The property features guest rooms and spacious bungalows with private terraces, modern amenities, and decor that blends contemporary comfort with traditional Vietnamese craftsmanship. Highlighted services include a Vietnamese-Western restaurant, Lantern Spa, complimentary bike rental and easy access to nearby attractions.', 'Phường Tây Hoa Lư, Ninh Bình', 'Tay Hoa Lu Ward, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000D769A4A5F2765A40AC90F2936A473440', NULL, NULL, 'VND', 0, 0, 'inactive', FALSE, '00:54.8', '22:14.0'),
    (59, 'khu-bao-ton-thien-nhien', 'Vân Long', 'Van Long', 'van-long-ninh-binh', 'Khu bảo tồn thiên nhiên Vân Long. Vị trí: Nằm trên đất liền. Đề xuất năm: 2001. Quản lý bởi: Ủy ban nhân dân tỉnh Ninh Bình.', 'Van Long Nature Reserve. Location: Mainland. Proposed in: 2001. Managed by: People''s Committee of Ninh Binh province.', 'Gia Viễn, Ninh Bình', 'Gia Vien, Ninh Binh', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, 'inactive', FALSE, '15:58.5', '22:14.0'),
    (60, 'khu-bao-ton-thien-nhien', 'Hoa Lư', 'Hoa Lu', 'hoa-lu-ninh-binh', 'Khu bảo vệ cảnh quan Hoa Lư. Vị trí: Nằm trên đất liền. Đề xuất năm: 2014. Quản lý bởi: Ủy ban nhân dân tỉnh Ninh Bình.', 'Hoa Lu Landscape Protection Area. Location: Mainland. Proposed in: 2014. Managed by: People''s Committee of Ninh Binh province.', 'Hoa Lư, Ninh Bình', 'Hoa Lu, Ninh Binh', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, 'inactive', FALSE, '15:58.5', '22:14.0'),
    (61, 'rung', 'Xuân Thủy', 'Xuan Thuy', 'xuan-thuy-ninh-binh', 'Vườn quốc gia Xuân Thủy. Vị trí: Nằm dọc bờ biển. Đề xuất năm: 2003. Quản lý bởi: Ủy ban nhân dân tỉnh Nam Định.', 'Xuan Thuy National Park. Location: Coastal. Proposed in: 2003. Managed by: People''s Committee of Nam Dinh province.', 'Giao Thủy, Nam Định', 'Giao Thuy, Nam Dinh', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, 'inactive', FALSE, '15:58.5', '22:14.0'),
    (62, 'vuon-thu', 'Vườn chim Thung Nham', 'Vườn chim Thung Nham', 'vuon-chim-thung-nham-ninh-binh', 'Vườn chim Thung Nham là nơi sinh sống của nhiều loài chim quý. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Vườn chim Thung Nham là nơi sinh sống của nhiều loài chim quý. Lorem ipsum dolor sit amet, consectetur adipiscing elit.', 'Thung Nham', 'Thung Nham', NULL, NULL, NULL, '0101000020E61000001B2FDD2406795A407F6ABC7493383440', '{"default": "6:00 - 18:00"}', 100000, 'VND', 4.4, 2703, 'inactive', FALSE, '17:14.2', '22:14.0'),
    (63, 'khu-du-lich', 'Tam Cốc', 'Tam Coc', 'tam-coc-ninh-binh', 'Một phần của quần thể danh thắng Tràng An, nổi tiếng với hệ thống hang động và cảnh quan sông nước.', 'Part of the Trang An scenic complex, famous for its cave systems and river landscapes.', 'Ninh Hải, Hoa Lư, Ninh Bình', 'Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E610000089B7CEBF5D7E5A40BA4C4D8237443440', '{"default": "07:00 - 18:00"}', 120000, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (64, 'di-tich-lich-su', 'Đình Các', 'Cac Communal House', 'inh-cac-ninh-binh', 'Ngôi đình cổ nằm trong tuyến du lịch Tam Cốc, mang giá trị lịch sử và kiến trúc.', 'An ancient communal house located on the Tam Coc tourist route, with historical and architectural value.', 'Tam Cốc, Ninh Hải, Hoa Lư, Ninh Bình', 'Tam Coc, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000003A90F5D4EA7E5A401041D5E8D5443440', '{"default": "07:00 - 18:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (65, 'den-chua', 'Đền Thung Nhang', 'Thung Nhang Temple', 'en-thung-nhang-ninh-binh', 'Một ngôi đền cổ khác trong khu vực, mang không gian thanh tịnh.', 'Another ancient temple in the area, offering a tranquil atmosphere.', 'Đam Khê, Ninh Hải, Hoa Lư, Ninh Bình', 'Dam Khe, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000004374081C09805A403BC5AA4198473440', '{"default": "07:00 - 17:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (66, 'den-chua', 'Đền Vối', 'Voi Temple', 'en-voi-ninh-binh', 'Đền Vối cổ kính, nơi gắn liền với nhiều câu chuyện lịch sử của vùng đất Hoa Lư.', 'The ancient Voi Temple, associated with many historical stories of the Hoa Lu region.', 'Ninh Hải, Hoa Lư, Ninh Bình', 'Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000004B72C0AE267A5A40AF44A0FA07593440', '{"default": "08:00 - 17:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (67, 'hang-dong', 'Động Tiên Cá', 'Fairy Fish Cave', 'ong-tien-ca-ninh-binh', 'Hang động huyền ảo với những câu chuyện truyền thuyết về tiên cá.', 'A mystical cave with legends about mermaids.', 'Sơn Hà, Nho Quan, Ninh Bình', 'Son Ha, Nho Quan, Ninh Binh', NULL, NULL, NULL, '0101000020E610000049BDA772DA785A40E277D32D3B4C3440', '{"default": "08:00 - 16:30"}', 50000, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (68, 'khu-du-lich', 'Đường lên Hang Múa', 'Mua Caves Ecolodge (viewpoint)', 'uong-len-hang-mua-ninh-binh', 'Con đường gồm 500 bậc đá dẫn lên đỉnh núi Múa, nơi có thể ngắm trọn vẹn cảnh Tam Cốc.', 'A path of 500 stone steps leading to the peak of Mua Mountain, offering a complete view of Tam Coc.', 'Khê Đầu Hạ, Hoa Lư, Ninh Bình', 'Khe Dau Ha, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000F29716F5497D5A408EC8772975393440', '{"default": "06:00 - 19:00"}', 100000, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (69, 'khu-du-lich', 'Cánh đồng Sen', 'Lotus Field', 'canh-ong-sen-ninh-binh', 'Cánh đồng sen rộng lớn, là địa điểm chụp ảnh nổi tiếng, đặc biệt vào mùa hạ.', 'A large lotus field, a famous photo spot, especially in the summer.', 'Tam Cốc, Ninh Hải, Hoa Lư, Ninh Bình', 'Tam Coc, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000952C27A1F47B5A406CCD565EF23B3440', '{"default": "06:00 - 18:00"}', 20000, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (70, 'den-chua', 'Đền Trình', 'Trinh Temple', 'en-trinh-ninh-binh', 'Điểm dừng đầu tiên trên tuyến du lịch Tràng An, nơi du khách làm lễ trước khi bắt đầu hành trình.', 'The first stop on the Trang An tourist route, where visitors pay respects before starting their journey.', 'Tràng An, Hoa Lư, Ninh Bình', 'Trang An, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000EFCB99ED0A7A5A40963D096CCE413440', '{"default": "07:00 - 17:00"}', 0, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (71, 'hang-dong', 'Hang Vồng', 'Vong Cave', 'hang-vong-ninh-binh', 'Một trong các hang động trên tuyến du lịch Tràng An.', 'One of the caves on the Trang An tourist route.', 'Tràng An, Hoa Lư, Ninh Bình', 'Trang An, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C364AA60547A5A406F1283C0CA413440', '{"default": "07:00 - 17:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (72, 'den-chua', 'Đền Suối Tiên', 'Suoi Tien Temple', 'en-suoi-tien-ninh-binh', 'Ngôi đền nằm cạnh dòng suối trong mát, không gian linh thiêng và yên bình.', 'A temple located next to a clear stream, with a sacred and peaceful atmosphere.', 'Tràng An, Hoa Lư, Ninh Bình', 'Trang An, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000005D6BEF53557A5A4083A62556463F3440', '{"default": "07:00 - 17:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (73, 'den-chua', 'Đền Trần', 'Tran Temple', 'en-tran-ninh-binh', 'Nơi thờ các vị vua nhà Trần và các vị tướng có công, một di tích quan trọng của Cố đô Hoa Lư.', 'A place of worship for Tran dynasty kings and meritorious generals, an important relic of Hoa Lu Ancient Capital.', 'Cố đô Hoa Lư, Trường Yên, Hoa Lư, Ninh Bình', 'Hoa Lu Ancient Capital, Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000A8C64B3789795A40E17A14AE47413440', '{"default": "07:00 - 18:00"}', 20000, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (74, 'di-tich-lich-su', 'Phủ Khống', 'Khong Temple', 'phu-khong-ninh-binh', 'Nơi thờ 7 vị quan trung thần nhà Đinh, nằm trên tuyến du lịch Tràng An.', 'A place of worship for 7 loyal mandarins of the Dinh dynasty, located on the Trang An tourist route.', 'Tràng An, Hoa Lư, Ninh Bình', 'Trang An, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E610000060E5D022DB795A4017D9CEF753433440', '{"default": "07:00 - 17:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (75, 'den-chua', 'Đền thánh Cao Sơn', 'Cao Son Saint Temple', 'en-thanh-cao-son-ninh-binh', 'Ngôi đền thờ Tứ vị Thánh nương, nằm trong khu di tích Cố đô Hoa Lư.', 'A temple dedicated to the Four Holy Mothers, located in the Hoa Lu Ancient Capital relic site.', 'Cố đô Hoa Lư, Trường Yên, Hoa Lư, Ninh Bình', 'Hoa Lu Ancient Capital, Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000D122DBF97E7A5A401B2FDD2406413440', '{"default": "07:00 - 18:00"}', 0, 'VND', 0, 0, 'inactive', FALSE, '01:26.5', '01:26.5'),
    (76, 'di-tich-lich-su', 'Hành cung Vũ Lâm', 'Vu Lam Royal Step-over Palace', 'hanh-cung-vu-lam-ninh-binh', 'Căn cứ quân sự thời nhà Trần, nơi các vua Trần từng tu hành, mang giá trị lịch sử to lớn.', 'A military base of the Tran dynasty, where Tran kings practiced, holding great historical value.', 'Ninh Hải, Hoa Lư, Ninh Bình', 'Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000C3F5285C8F7A5A40AC1C5A643B3F3440', '{"default": "08:00 - 17:00"}', 0, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (77, 'den-chua', 'Chùa Bái Đính cổ', 'Ancient Bai Dinh Pagoda', 'chua-bai-inh-co-ninh-binh', 'Ngôi chùa cổ nằm trên núi Bái Đính, là một phần của quần thể chùa Bái Đính lớn.', 'An ancient pagoda located on Bai Dinh mountain, part of the larger Bai Dinh pagoda complex.', 'Gia Sinh, Gia Viễn, Ninh Bình', 'Gia Sinh, Gia Vien, Ninh Binh', NULL, NULL, NULL, '0101000020E61000008195438B6C775A4085EB51B81E453440', '{"default": "06:00 - 21:00"}', 0, 'VND', 0, 0, 'active', FALSE, '01:26.5', '06:32.3'),
    (78, 'den-chua', 'Đền Vua Đinh', 'King Dinh Temple', 'en-vua-inh-ninh-binh', 'Đền thờ vua Đinh Tiên Hoàng, một trong hai đền chính tại Cố đô Hoa Lư.', 'A temple dedicated to King Dinh Tien Hoang, one of the two main temples at Hoa Lu Ancient Capital.', 'Cố đô Hoa Lư, Trường Yên, Hoa Lư, Ninh Bình', 'Hoa Lu Ancient Capital, Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000448B6CE7FB795A4062105839B4483440', '{"default": "07:00 - 18:00"}', 20000, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (79, 'den-chua', 'Đền Vua Lê', 'King Le Temple', 'en-vua-le-ninh-binh', 'Đền thờ vua Lê Đại Hành, nằm cạnh đền vua Đinh trong khu di tích Cố đô Hoa Lư.', 'A temple dedicated to King Le Dai Hanh, located next to the King Dinh temple in the Hoa Lu Ancient Capital relic site.', 'Cố đô Hoa Lư, Trường Yên, Hoa Lư, Ninh Bình', 'Hoa Lu Ancient Capital, Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000355EBA490C7A5A40F0A7C64B37493440', '{"default": "07:00 - 18:00"}', 20000, 'VND', 0, 0, 'active', FALSE, '01:26.5', '01:26.5'),
    (80, 'den-chua', 'Đền Thái Vi', 'Thai Vi Temple', 'en-thai-vi-ninh-binh', 'Đền Thái Vi nằm trong quần thể khu du lịch Tam Cốc – Bích Động, thuộc thôn Văn Lâm, xã Ninh Hải, huyện Hoa Lư, tỉnh Ninh Bình. Đây là ngôi đền thờ các vị vua và tướng lĩnh của vương triều Trần – triều đại hùng mạnh thế kỷ XIII, nổi tiếng với ba lần chiến thắng quân Nguyên – Mông.
Sau khi nhà Trần lập Hành cung Vũ Lâm, nhân dân địa phương đã dựng am Thái Vi, sau trở thành đền Thái Vi, nơi tưởng nhớ công lao các vua Trần. Trải qua nhiều lần trùng tu qua các thời Lê, Nguyễn, đến nay đền vẫn giữ kiến trúc cổ theo kiểu “nội công ngoại quốc”, tức bên ngoài hình chữ “Quốc”, bên trong hình chữ “Công”.
Trước đền là giếng ngọc trong vắt quanh năm, sau đền là núi Cấm Sơn, tạo nên thế “Tiền Ngọc tỉnh, hậu Cấm Sơn”. Hai bên cổng là ngựa đá xanh – biểu tượng cho chiến công của triều Trần. Bước vào trong, du khách sẽ thấy gác chuông bằng gỗ lim, tháp bia, sân rồng lát đá xanh, và những cột đá chạm khắc long, ly, quy, phượng vô cùng tinh xảo.
Trong chính điện thờ bốn vị vua Trần:


Trần Thái Tông – vị vua đầu tiên của nhà Trần, người đặt nền móng cho triều đại và lãnh đạo cuộc kháng chiến chống Nguyên – Mông lần thứ nhất.


Trần Thánh Tông, Trần Nhân Tông, Trần Anh Tông – các đời vua tiếp theo, có công lớn trong việc củng cố, phát triển đất nước và giữ yên bờ cõi.
Ngoài ra còn có tượng Hoàng Thái Hậu Thuận Thiên và hai tượng kim đồng, ngọc nữ đứng hầu.


Hàng năm, từ ngày 14 đến 17 tháng 3 âm lịch, lễ hội đền Thái Vi được tổ chức, xưa kia là “Quốc lễ”, nay trở thành hội làng lớn của vùng Hoa Lư. Lễ hội gồm hai phần:


Phần lễ có rước kiệu và tế lễ trang nghiêm, với hàng chục đoàn rước từ khắp nơi trong tỉnh Ninh Bình.


Phần hội diễn ra sôi nổi với các trò chơi dân gian như múa lân, múa rồng, đấu vật, đánh cờ người, bơi thuyền, thu hút đông đảo du khách.


Đền Thái Vi không chỉ là nơi tưởng niệm công đức các vua Trần mà còn là biểu tượng văn hoá – lịch sử của Ninh Bình, gợi nhắc truyền thống “uống nước nhớ nguồn” của dân tộc Việt Nam.
Trong không gian non nước hữu tình của Tam Cốc – Bích Động, đến với đền Thái Vi là dịp để con người tìm lại sự thanh tịnh, lòng tự hào dân tộc và biết ơn những bậc tiền nhân đã góp phần dựng xây non sông gấm vóc.', 'Thai Vi Temple is located within the Tam Coc – Bich Dong tourist complex, in Van Lam Village, Ninh Hai Commune, Hoa Lu District, Ninh Binh Province. This temple is dedicated to the Tran Dynasty kings and generals, one of Vietnam’s most powerful dynasties in the 13th century, renowned for their three victories over the Mongol invasions.
After the Tran kings established Vu Lam Palace, local residents built a small shrine called Thai Vi Am, which later became Thai Vi Temple, to honor the dynasty’s great contributions. Through many restorations under the Le and Nguyen Dynasties, the temple has retained its ancient architectural style known as “Noi Cong Ngoai Quoc” — meaning the outer layout resembles the Chinese character “Quoc” (國), while the inner structure forms the character “Cong” (工).
In front of the temple lies a clear jade well, and behind it rises Cam Son Mountain, creating the feng shui balance “Ngoc well in front, Cam Son behind.” On both sides of the entrance stand two stone horses, symbolizing the enduring spirit of the Tran kings. Inside, visitors can admire the wooden bell tower, stone steles, dragon courtyard paved with green stone, and intricately carved stone columns depicting dragons, phoenixes, turtles, and carp transforming into dragons — all showcasing superb craftsmanship.
The temple enshrines four Tran kings:


Tran Thai Tong – the first king of the Tran Dynasty, who laid the foundations of the regime and led Vietnam to victory in the first war against the Mongols.


Tran Thanh Tong, Tran Nhan Tong, and Tran Anh Tong – successive kings who strengthened the dynasty and ensured peace and prosperity for the nation.
Also worshiped are Queen Mother Thuan Thien and statues of Golden Boy and Jade Girl standing beside the kings.


Every year, from the 14th to the 17th of the third lunar month, the Thai Vi Temple Festival is held. In ancient times, it was a national ceremony, and today it has become one of the largest local festivals in Hoa Lu. The festival has two main parts:


The ritual section includes solemn processions and offering ceremonies, with dozens of processional teams from villages across Ninh Binh.


The festive section features lively traditional activities such as lion and dragon dances, wrestling, human chess, and boat racing, creating a vibrant and joyful atmosphere.


Thai Vi Temple is not only a sacred place commemorating the Tran Dynasty’s glorious contributions but also a symbol of Vietnamese cultural and historical heritage. Amid the serene natural scenery of Tam Coc – Bich Dong, visiting Thai Vi Temple offers a moment of peace, pride, and gratitude — a reminder of the enduring Vietnamese spirit of “remembering the source while drinking the water.”', 'Văn Lâm, Ninh Hải, Hoa Lư, Ninh Bình', 'Văn Lâm, Ninh Hải, Hoa Lư, Ninh Bình', NULL, NULL, NULL, '0101000020E6100000629A3A30837B5A407A4DF98866393440', '{"default": "07:30 - 17:30"}', 0, 'VND', 0, 0, 'active', FALSE, '01:26.5', '17:33.0'),
    (81, 'nha-hang', 'Nhà hàng Tre Xanh', 'Green Bamboo Restaurant', 'nha-hang-tre-xanh-ninh-binh', 'Nhà hàng chuyên phục vụ các món ăn đặc sản vùng Ninh Bình như cơm cháy, dê núi, cá sông. Không gian thoáng mát với thiết kế gần gũi với thiên nhiên.', 'Restaurant specializing in Ninh Binh specialties such as rice crackers, mountain goat, river fish. Airy space with nature-friendly design.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000007B14AE47E17A5A40FCA9F1D24D423440', '{"default": "6:00 - 22:00"}', NULL, 'VND', 0, 0, 'inactive', FALSE, '09:14.0', '54:55.0'),
    (82, 'nui', 'Núi Ngu Động', 'Ngu Dong Mountain', 'nui-ngu-ong-ninh-binh', 'Núi Ngu Động cao 209m, nổi tiếng với 5 hang động xuyên qua lòng núi. Từ đỉnh núi có thể ngắm toàn cảnh quần thể Tràng An với vẻ đẹp như tranh vẽ.', 'Ngu Dong Mountain is 209m high, famous for 5 caves through the mountain. From the top you can see the entire Trang An complex with picturesque beauty.', 'Tràng An, Ninh Hải, Hoa Lư, Ninh Bình', 'Trang An, Ninh Hai, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E6100000DF4F8D976E7A5A409BFEEC478A403440', '{"default": "8:00 - 17:00"}', 50000, 'VND', 2.36, 11, 'active', FALSE, '09:14.0', '23:07.3'),
    (83, 'di-tich-lich-su', 'Cố đô Hoa Lư', 'Ancient Capital Hoa Lu', 'co-o-hoa-lu-ninh-binh', 'Cố đô Hoa Lư là thủ đô đầu tiên của Việt Nam thời phong kiến dưới triều Đinh và Lê. Nơi đây lưu giữ nhiều di tích lịch sử quan trọng và câu chuyện về anh hùng dân tộc.', 'Ancient Capital Hoa Lu was the first capital of feudal Vietnam under Dinh and Le dynasties. This place preserves many important historical relics and stories about national heroes.', 'Trường Yên, Hoa Lư, Ninh Bình', 'Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E610000033333333337B5A40C3F5285C8F423440', '{"default": "7:30 - 17:00"}', 20000, 'VND', 0, 0, 'active', FALSE, '09:14.0', '31:15.4'),
    (84, 'den-chua', 'Đền Đinh Tiên Hoàng', 'Dinh Tien Hoang Temple', 'en-inh-tien-hoang-ninh-binh', 'Đền thờ Hoàng đế Đinh Tiên Hoàng - vị vua đầu tiên của nước Đại Cồ Việt. Kiến trúc đền mang đậm nét truyền thống Việt Nam với những chi tiết trang trí tinh xảo.', 'Temple worshipping Emperor Dinh Tien Hoang - the first king of Dai Co Viet. The temple architecture bears strong Vietnamese traditions with elaborate decorative details.', 'Cố đô Hoa Lư, Trường Yên, Hoa Lư, Ninh Bình', 'Hoa Lu Ancient Capital, Truong Yen, Hoa Lu, Ninh Binh', NULL, NULL, NULL, '0101000020E61000004260E5D0227B5A40DF4F8D976E423440', '{"default": "7:30 - 17:00"}', 0, 'VND', 0, 0, 'active', FALSE, '09:14.0', '09:14.0')
), normalized AS (
  SELECT
    sr.*,
    sc.id AS category_id,
    ST_SetSRID(
      CASE
        WHEN GeometryType(ST_GeomFromEWKB(decode(sr.geometry_hex, 'hex'))) = 'POINT'
          THEN ST_GeomFromEWKB(decode(sr.geometry_hex, 'hex'))
        ELSE ST_PointOnSurface(ST_GeomFromEWKB(decode(sr.geometry_hex, 'hex')))
      END,
      4326
    )::geometry(POINT, 4326) AS geom_point
  FROM source_rows sr
  JOIN spot_categories sc ON sc.code = sr.category_code
)
INSERT INTO tourism_spots (
  category_id, province_code, name_vi, name_en, slug,
  description_vi, description_en, address_vi, address_en, geom,
  opening_hours, ticket_price_adult, ticket_price_child, ticket_currency,
  phone, email, website, rating_avg, rating_count, status, is_featured, created_at, updated_at
)
SELECT
  category_id, '37', name_vi, name_en, slug,
  description_vi, description_en, address_vi, address_en, geom_point,
  COALESCE(opening_hours::jsonb, '{}'::jsonb), entrance_fee, NULL, COALESCE(currency, 'VND'),
  phone, email, website, COALESCE(rating_avg, 0), COALESCE(rating_count::integer, 0), status, is_featured,
  NOW(), NOW()
FROM normalized
ON CONFLICT (slug) DO UPDATE SET
  category_id = EXCLUDED.category_id,
  province_code = EXCLUDED.province_code,
  name_vi = EXCLUDED.name_vi,
  name_en = EXCLUDED.name_en,
  description_vi = EXCLUDED.description_vi,
  description_en = EXCLUDED.description_en,
  address_vi = EXCLUDED.address_vi,
  address_en = EXCLUDED.address_en,
  geom = EXCLUDED.geom,
  opening_hours = EXCLUDED.opening_hours,
  ticket_price_adult = EXCLUDED.ticket_price_adult,
  ticket_price_child = EXCLUDED.ticket_price_child,
  ticket_currency = EXCLUDED.ticket_currency,
  phone = EXCLUDED.phone,
  email = EXCLUDED.email,
  website = EXCLUDED.website,
  rating_avg = EXCLUDED.rating_avg,
  rating_count = EXCLUDED.rating_count,
  status = EXCLUDED.status,
  is_featured = EXCLUDED.is_featured,
  updated_at = EXCLUDED.updated_at;

